INSERT INTO `product_levels` (`id`, `course_id`, `skill_level`, `skill_level_jp`, `purpose`, `purpose_jp`, `learn_info`, `learn_info_jp`, `outcome`, `outcome_jp`, `price`, `price_jp`, `price_hk`, `price_in_points`, `created_at`, `updated_at`) VALUES
(1, 1, 'Small', '小さい', '(2048 × 2048 px) – Designed for compact digital use, the small version of Sakura Schoolyard Daydream preserves the full atmosphere of the original artwork while optimizing clarity for mobile wallpapers, social media posts, thumbnails, and small decorative prints. Even at a reduced scale, the drifting cherry blossom petals, golden afternoon light, and the student\'s wistful expression remain visually impactful, making this format ideal for digital collectors, online portfolios, and aesthetic showcases where clean presentation matters most.', '（2048 × 2048 px）小サイズ版は、原作の雰囲気を保ちながら、モバイル壁紙、SNS投稿、サムネイル、小型プリント向けに最適化されています。舞い散る桜の花びら、黄金色の午後の光、物思いにふける学生の表情が小さなサイズでも鮮明に表現され、デジタルコレクションやオンラインポートフォリオに最適な仕様です。', 'The Sakura Schoolyard Daydream artwork captures anime-style character illustration, cherry blossom scenery, and nostalgic school-life storytelling through expressive composition and carefully balanced visual storytelling.', '「Sakura Schoolyard Daydream」は、表現力豊かな構成とバランスの取れたビジュアルストーリーテリングを通じて、アニメ調のキャラクター描写、桜の風景、そして懐かしい学園生活のストーリーテリングを表現しています。', 'Gain an understanding of anime slice-of-life composition, soft cel-shaded lighting, and emotional visual storytelling techniques used throughout this decorative artwork.', 'この装飾アートワークに用いられている日常系アニメの構図、柔らかなセル画調の光表現、感情豊かなビジュアルストーリーテリングの技法への理解を深めることができます。', 105.00, 105.00, 105.00, 105, NULL, NULL),
(2, 1, 'Medium', 'ミディアム', '(4096 × 4096 px) – The medium version offers enhanced detail, richer textures, and deeper visual immersion, making it perfect for framed wall décor, posters, desktop wallpapers, and modern interior styling. In this format, the drifting cherry blossom petals, golden afternoon light, and the student\'s wistful expression become more detailed and expressive, providing a balanced choice between portability and visual richness that suits both digital display and physical presentation.', '（4096 × 4096 px）中サイズ版は、より豊かなディテールと質感、深い没入感を実現し、フレームアート、ポスター、デスクトップ壁紙、モダンインテリアに最適です。舞い散る桜の花びら、黄金色の午後の光、物思いにふける学生の表情がより精細で表現豊かになり、デジタルと物理的な展示の両方に対応するバランスの取れた仕様です。', 'The Sakura Schoolyard Daydream artwork presents immersive scenery featuring anime-style character illustration, cherry blossom scenery, and nostalgic school-life storytelling, layered artistic textures, and atmospheric detail designed for engaging decorative experiences.', '「Sakura Schoolyard Daydream」は、アニメ調のキャラクター描写、桜の風景、そして懐かしい学園生活のストーリーテリング、重層的な芸術的テクスチャ、そして空気感のあるディテールを備えた没入型の情景を提示します。', 'Develop deeper knowledge of anime slice-of-life composition, soft cel-shaded lighting, and emotional visual storytelling techniques through layered composition and atmospheric detail.', '重層的な構成と空気感のあるディテールを通じて、日常系アニメの構図、柔らかなセル画調の光表現、感情豊かなビジュアルストーリーテリングの技法の知識をより深めることができます。', 280.00, 280.00, 280.00, 280, NULL, NULL),
(3, 1, 'Large', '大きい', '(8192 × 8192 px) – The large-format version transforms Sakura Schoolyard Daydream into a fully immersive visual experience designed for canvas prints, galleries, luxury interiors, and large wall installations. Every detail of the drifting cherry blossom petals, golden afternoon light, and the student\'s wistful expression is rendered with exceptional clarity and depth in this premium resolution, turning any environment into a striking artistic statement with gallery-quality presence.', '（8192 × 8192 px）大サイズ版は、「Sakura Schoolyard Daydream」を完全没入型のビジュアル体験へと昇華させたプレミアム仕様です。舞い散る桜の花びら、黄金色の午後の光、物思いにふける学生の表情が超高精細に描写され、キャンバスプリント、ギャラリー展示、高級インテリア、大型ウォールアートに最適な、圧倒的な存在感を放つ作品となります。', 'The Sakura Schoolyard Daydream artwork transforms interiors through expansive compositions featuring anime-style character illustration, cherry blossom scenery, and nostalgic school-life storytelling and visually rich, gallery-scale artistic storytelling.', '「Sakura Schoolyard Daydream」は、アニメ調のキャラクター描写、桜の風景、そして懐かしい学園生活のストーリーテリングと視覚的に豊かなギャラリースケールの芸術表現を備えた壮大な構成で、空間を一変させます。', 'Explore an expansive artistic presentation of anime slice-of-life composition, soft cel-shaded lighting, and emotional visual storytelling techniques through immersive, gallery-scale visual storytelling.', '没入型のギャラリースケールの視覚表現を通じて、日常系アニメの構図、柔らかなセル画調の光表現、感情豊かなビジュアルストーリーテリングの技法の壮大な芸術的プレゼンテーションを体験できます。', 420.00, 420.00, 420.00, 420, NULL, NULL),
(4, 2, 'Small', '小さい', '(2048 × 2048 px) – Designed for compact digital use, the small version of Midnight Ramen Stand preserves the full atmosphere of the original artwork while optimizing clarity for mobile wallpapers, social media posts, thumbnails, and small decorative prints. Even at a reduced scale, the glowing red lanterns, rising steam, and wet pavement reflections of the midnight street remain visually impactful, making this format ideal for digital collectors, online portfolios, and aesthetic showcases where clean presentation matters most.', '（2048 × 2048 px）小サイズ版は、原作の雰囲気を保ちながら、モバイル壁紙、SNS投稿、サムネイル、小型プリント向けに最適化されています。赤提灯の輝き、立ちのぼる湯気、濡れた路面に映る深夜の街の光が小さなサイズでも鮮明に表現され、デジタルコレクションやオンラインポートフォリオに最適な仕様です。', 'The Midnight Ramen Stand artwork captures cozy anime night scenery, Japanese street food culture, and warm-versus-cool lighting contrast through expressive composition and carefully balanced visual storytelling.', '「Midnight Ramen Stand」は、表現力豊かな構成とバランスの取れたビジュアルストーリーテリングを通じて、温かなアニメの夜景、日本の屋台文化、暖色と寒色の光のコントラストを表現しています。', 'Gain an understanding of atmospheric night-scene lighting, environmental storytelling, and inviting urban anime aesthetics used throughout this decorative artwork.', 'この装飾アートワークに用いられている夜のシーンの空気感ある光表現、環境によるストーリーテリング、心温まる都市アニメの美学への理解を深めることができます。', 114.00, 114.00, 114.00, 114, NULL, NULL),
(5, 2, 'Medium', 'ミディアム', '(4096 × 4096 px) – The medium version offers enhanced detail, richer textures, and deeper visual immersion, making it perfect for framed wall décor, posters, desktop wallpapers, and modern interior styling. In this format, the glowing red lanterns, rising steam, and wet pavement reflections of the midnight street become more detailed and expressive, providing a balanced choice between portability and visual richness that suits both digital display and physical presentation.', '（4096 × 4096 px）中サイズ版は、より豊かなディテールと質感、深い没入感を実現し、フレームアート、ポスター、デスクトップ壁紙、モダンインテリアに最適です。赤提灯の輝き、立ちのぼる湯気、濡れた路面に映る深夜の街の光がより精細で表現豊かになり、デジタルと物理的な展示の両方に対応するバランスの取れた仕様です。', 'The Midnight Ramen Stand artwork presents immersive scenery featuring cozy anime night scenery, Japanese street food culture, and warm-versus-cool lighting contrast, layered artistic textures, and atmospheric detail designed for engaging decorative experiences.', '「Midnight Ramen Stand」は、温かなアニメの夜景、日本の屋台文化、暖色と寒色の光のコントラスト、重層的な芸術的テクスチャ、そして空気感のあるディテールを備えた没入型の情景を提示します。', 'Develop deeper knowledge of atmospheric night-scene lighting, environmental storytelling, and inviting urban anime aesthetics through layered composition and atmospheric detail.', '重層的な構成と空気感のあるディテールを通じて、夜のシーンの空気感ある光表現、環境によるストーリーテリング、心温まる都市アニメの美学の知識をより深めることができます。', 304.00, 304.00, 304.00, 304, NULL, NULL),
(6, 2, 'Large', '大きい', '(8192 × 8192 px) – The large-format version transforms Midnight Ramen Stand into a fully immersive visual experience designed for canvas prints, galleries, luxury interiors, and large wall installations. Every detail of the glowing red lanterns, rising steam, and wet pavement reflections of the midnight street is rendered with exceptional clarity and depth in this premium resolution, turning any environment into a striking artistic statement with gallery-quality presence.', '（8192 × 8192 px）大サイズ版は、「Midnight Ramen Stand」を完全没入型のビジュアル体験へと昇華させたプレミアム仕様です。赤提灯の輝き、立ちのぼる湯気、濡れた路面に映る深夜の街の光が超高精細に描写され、キャンバスプリント、ギャラリー展示、高級インテリア、大型ウォールアートに最適な、圧倒的な存在感を放つ作品となります。', 'The Midnight Ramen Stand artwork transforms interiors through expansive compositions featuring cozy anime night scenery, Japanese street food culture, and warm-versus-cool lighting contrast and visually rich, gallery-scale artistic storytelling.', '「Midnight Ramen Stand」は、温かなアニメの夜景、日本の屋台文化、暖色と寒色の光のコントラストと視覚的に豊かなギャラリースケールの芸術表現を備えた壮大な構成で、空間を一変させます。', 'Explore an expansive artistic presentation of atmospheric night-scene lighting, environmental storytelling, and inviting urban anime aesthetics through immersive, gallery-scale visual storytelling.', '没入型のギャラリースケールの視覚表現を通じて、夜のシーンの空気感ある光表現、環境によるストーリーテリング、心温まる都市アニメの美学の壮大な芸術的プレゼンテーションを体験できます。', 456.00, 456.00, 456.00, 456, NULL, NULL),
(7, 3, 'Small', '小さい', '(2048 × 2048 px) – Designed for compact digital use, the small version of The Shrine Maiden\'s Umbrella preserves the full atmosphere of the original artwork while optimizing clarity for mobile wallpapers, social media posts, thumbnails, and small decorative prints. Even at a reduced scale, the crimson paper umbrella, weathered torii gate, and delicate rain streaks in the mist remain visually impactful, making this format ideal for digital collectors, online portfolios, and aesthetic showcases where clean presentation matters most.', '（2048 × 2048 px）小サイズ版は、原作の雰囲気を保ちながら、モバイル壁紙、SNS投稿、サムネイル、小型プリント向けに最適化されています。紅い和傘、風化した鳥居、霧の中の繊細な雨の筋が小さなサイズでも鮮明に表現され、デジタルコレクションやオンラインポートフォリオに最適な仕様です。', 'The The Shrine Maiden\'s Umbrella artwork captures traditional Japanese shrine imagery, rain atmosphere rendering, and anime-style color accents through expressive composition and carefully balanced visual storytelling.', '「The Shrine Maiden\'s Umbrella」は、表現力豊かな構成とバランスの取れたビジュアルストーリーテリングを通じて、日本の神社の伝統的イメージ、雨の空気感の描写、アニメ調の色彩アクセントを表現しています。', 'Gain an understanding of harmonious color composition, serene mood building, and the blend of tradition with anime aesthetics used throughout this decorative artwork.', 'この装飾アートワークに用いられている調和のとれた色彩構成、静謐な雰囲気づくり、伝統とアニメ美学の融合への理解を深めることができます。', 126.00, 126.00, 126.00, 126, NULL, NULL),
(8, 3, 'Medium', 'ミディアム', '(4096 × 4096 px) – The medium version offers enhanced detail, richer textures, and deeper visual immersion, making it perfect for framed wall décor, posters, desktop wallpapers, and modern interior styling. In this format, the crimson paper umbrella, weathered torii gate, and delicate rain streaks in the mist become more detailed and expressive, providing a balanced choice between portability and visual richness that suits both digital display and physical presentation.', '（4096 × 4096 px）中サイズ版は、より豊かなディテールと質感、深い没入感を実現し、フレームアート、ポスター、デスクトップ壁紙、モダンインテリアに最適です。紅い和傘、風化した鳥居、霧の中の繊細な雨の筋がより精細で表現豊かになり、デジタルと物理的な展示の両方に対応するバランスの取れた仕様です。', 'The The Shrine Maiden\'s Umbrella artwork presents immersive scenery featuring traditional Japanese shrine imagery, rain atmosphere rendering, and anime-style color accents, layered artistic textures, and atmospheric detail designed for engaging decorative experiences.', '「The Shrine Maiden\'s Umbrella」は、日本の神社の伝統的イメージ、雨の空気感の描写、アニメ調の色彩アクセント、重層的な芸術的テクスチャ、そして空気感のあるディテールを備えた没入型の情景を提示します。', 'Develop deeper knowledge of harmonious color composition, serene mood building, and the blend of tradition with anime aesthetics through layered composition and atmospheric detail.', '重層的な構成と空気感のあるディテールを通じて、調和のとれた色彩構成、静謐な雰囲気づくり、伝統とアニメ美学の融合の知識をより深めることができます。', 336.00, 336.00, 336.00, 336, NULL, NULL),
(9, 3, 'Large', '大きい', '(8192 × 8192 px) – The large-format version transforms The Shrine Maiden\'s Umbrella into a fully immersive visual experience designed for canvas prints, galleries, luxury interiors, and large wall installations. Every detail of the crimson paper umbrella, weathered torii gate, and delicate rain streaks in the mist is rendered with exceptional clarity and depth in this premium resolution, turning any environment into a striking artistic statement with gallery-quality presence.', '（8192 × 8192 px）大サイズ版は、「The Shrine Maiden\'s Umbrella」を完全没入型のビジュアル体験へと昇華させたプレミアム仕様です。紅い和傘、風化した鳥居、霧の中の繊細な雨の筋が超高精細に描写され、キャンバスプリント、ギャラリー展示、高級インテリア、大型ウォールアートに最適な、圧倒的な存在感を放つ作品となります。', 'The The Shrine Maiden\'s Umbrella artwork transforms interiors through expansive compositions featuring traditional Japanese shrine imagery, rain atmosphere rendering, and anime-style color accents and visually rich, gallery-scale artistic storytelling.', '「The Shrine Maiden\'s Umbrella」は、日本の神社の伝統的イメージ、雨の空気感の描写、アニメ調の色彩アクセントと視覚的に豊かなギャラリースケールの芸術表現を備えた壮大な構成で、空間を一変させます。', 'Explore an expansive artistic presentation of harmonious color composition, serene mood building, and the blend of tradition with anime aesthetics through immersive, gallery-scale visual storytelling.', '没入型のギャラリースケールの視覚表現を通じて、調和のとれた色彩構成、静謐な雰囲気づくり、伝統とアニメ美学の融合の壮大な芸術的プレゼンテーションを体験できます。', 504.00, 504.00, 504.00, 504, NULL, NULL),
(10, 4, 'Small', '小さい', '(2048 × 2048 px) – Designed for compact digital use, the small version of Rooftop Confession at Dusk preserves the full atmosphere of the original artwork while optimizing clarity for mobile wallpapers, social media posts, thumbnails, and small decorative prints. Even at a reduced scale, the gradient dusk sky, chain-link fence silhouettes, and backlit rim lighting on the characters remain visually impactful, making this format ideal for digital collectors, online portfolios, and aesthetic showcases where clean presentation matters most.', '（2048 × 2048 px）小サイズ版は、原作の雰囲気を保ちながら、モバイル壁紙、SNS投稿、サムネイル、小型プリント向けに最適化されています。グラデーションの夕空、金網フェンスのシルエット、キャラクターを縁取る逆光が小さなサイズでも鮮明に表現され、デジタルコレクションやオンラインポートフォリオに最適な仕様です。', 'The Rooftop Confession at Dusk artwork captures romantic anime scene composition, golden-hour lighting, and emotional use of negative space through expressive composition and carefully balanced visual storytelling.', '「Rooftop Confession at Dusk」は、表現力豊かな構成とバランスの取れたビジュアルストーリーテリングを通じて、恋愛アニメのシーン構成、ゴールデンアワーの光、余白の感情的な使い方を表現しています。', 'Gain an understanding of cinematic dusk lighting, silhouette storytelling, and the visual language of coming-of-age anime used throughout this decorative artwork.', 'この装飾アートワークに用いられている映画的な夕暮れの光、シルエットによる物語表現、青春アニメの視覚言語への理解を深めることができます。', 108.00, 108.00, 108.00, 108, NULL, NULL),
(11, 4, 'Medium', 'ミディアム', '(4096 × 4096 px) – The medium version offers enhanced detail, richer textures, and deeper visual immersion, making it perfect for framed wall décor, posters, desktop wallpapers, and modern interior styling. In this format, the gradient dusk sky, chain-link fence silhouettes, and backlit rim lighting on the characters become more detailed and expressive, providing a balanced choice between portability and visual richness that suits both digital display and physical presentation.', '（4096 × 4096 px）中サイズ版は、より豊かなディテールと質感、深い没入感を実現し、フレームアート、ポスター、デスクトップ壁紙、モダンインテリアに最適です。グラデーションの夕空、金網フェンスのシルエット、キャラクターを縁取る逆光がより精細で表現豊かになり、デジタルと物理的な展示の両方に対応するバランスの取れた仕様です。', 'The Rooftop Confession at Dusk artwork presents immersive scenery featuring romantic anime scene composition, golden-hour lighting, and emotional use of negative space, layered artistic textures, and atmospheric detail designed for engaging decorative experiences.', '「Rooftop Confession at Dusk」は、恋愛アニメのシーン構成、ゴールデンアワーの光、余白の感情的な使い方、重層的な芸術的テクスチャ、そして空気感のあるディテールを備えた没入型の情景を提示します。', 'Develop deeper knowledge of cinematic dusk lighting, silhouette storytelling, and the visual language of coming-of-age anime through layered composition and atmospheric detail.', '重層的な構成と空気感のあるディテールを通じて、映画的な夕暮れの光、シルエットによる物語表現、青春アニメの視覚言語の知識をより深めることができます。', 288.00, 288.00, 288.00, 288, NULL, NULL),
(12, 4, 'Large', '大きい', '(8192 × 8192 px) – The large-format version transforms Rooftop Confession at Dusk into a fully immersive visual experience designed for canvas prints, galleries, luxury interiors, and large wall installations. Every detail of the gradient dusk sky, chain-link fence silhouettes, and backlit rim lighting on the characters is rendered with exceptional clarity and depth in this premium resolution, turning any environment into a striking artistic statement with gallery-quality presence.', '（8192 × 8192 px）大サイズ版は、「Rooftop Confession at Dusk」を完全没入型のビジュアル体験へと昇華させたプレミアム仕様です。グラデーションの夕空、金網フェンスのシルエット、キャラクターを縁取る逆光が超高精細に描写され、キャンバスプリント、ギャラリー展示、高級インテリア、大型ウォールアートに最適な、圧倒的な存在感を放つ作品となります。', 'The Rooftop Confession at Dusk artwork transforms interiors through expansive compositions featuring romantic anime scene composition, golden-hour lighting, and emotional use of negative space and visually rich, gallery-scale artistic storytelling.', '「Rooftop Confession at Dusk」は、恋愛アニメのシーン構成、ゴールデンアワーの光、余白の感情的な使い方と視覚的に豊かなギャラリースケールの芸術表現を備えた壮大な構成で、空間を一変させます。', 'Explore an expansive artistic presentation of cinematic dusk lighting, silhouette storytelling, and the visual language of coming-of-age anime through immersive, gallery-scale visual storytelling.', '没入型のギャラリースケールの視覚表現を通じて、映画的な夕暮れの光、シルエットによる物語表現、青春アニメの視覚言語の壮大な芸術的プレゼンテーションを体験できます。', 432.00, 432.00, 432.00, 432, NULL, NULL),
(13, 5, 'Small', '小さい', '(2048 × 2048 px) – Designed for compact digital use, the small version of Neon Idol Stage Debut preserves the full atmosphere of the original artwork while optimizing clarity for mobile wallpapers, social media posts, thumbnails, and small decorative prints. Even at a reduced scale, the magenta and cyan stage lights, falling confetti, and the ocean of glowing lightsticks remain visually impactful, making this format ideal for digital collectors, online portfolios, and aesthetic showcases where clean presentation matters most.', '（2048 × 2048 px）小サイズ版は、原作の雰囲気を保ちながら、モバイル壁紙、SNS投稿、サムネイル、小型プリント向けに最適化されています。マゼンタとシアンのステージ照明、舞い散る紙吹雪、光り輝くペンライトの海が小さなサイズでも鮮明に表現され、デジタルコレクションやオンラインポートフォリオに最適な仕様です。', 'The Neon Idol Stage Debut artwork captures dynamic concert scene composition, stage lighting effects, and idol culture visual energy through expressive composition and carefully balanced visual storytelling.', '「Neon Idol Stage Debut」は、表現力豊かな構成とバランスの取れたビジュアルストーリーテリングを通じて、ダイナミックなライブシーンの構成、ステージ照明の効果、アイドル文化の視覚的エネルギーを表現しています。', 'Gain an understanding of dramatic low-angle framing, particle and motion effects, and high-energy anime illustration techniques used throughout this decorative artwork.', 'この装飾アートワークに用いられている劇的なローアングル構図、パーティクルとモーション効果、躍動感あふれるアニメイラスト技法への理解を深めることができます。', 120.00, 120.00, 120.00, 120, NULL, NULL),
(14, 5, 'Medium', 'ミディアム', '(4096 × 4096 px) – The medium version offers enhanced detail, richer textures, and deeper visual immersion, making it perfect for framed wall décor, posters, desktop wallpapers, and modern interior styling. In this format, the magenta and cyan stage lights, falling confetti, and the ocean of glowing lightsticks become more detailed and expressive, providing a balanced choice between portability and visual richness that suits both digital display and physical presentation.', '（4096 × 4096 px）中サイズ版は、より豊かなディテールと質感、深い没入感を実現し、フレームアート、ポスター、デスクトップ壁紙、モダンインテリアに最適です。マゼンタとシアンのステージ照明、舞い散る紙吹雪、光り輝くペンライトの海がより精細で表現豊かになり、デジタルと物理的な展示の両方に対応するバランスの取れた仕様です。', 'The Neon Idol Stage Debut artwork presents immersive scenery featuring dynamic concert scene composition, stage lighting effects, and idol culture visual energy, layered artistic textures, and atmospheric detail designed for engaging decorative experiences.', '「Neon Idol Stage Debut」は、ダイナミックなライブシーンの構成、ステージ照明の効果、アイドル文化の視覚的エネルギー、重層的な芸術的テクスチャ、そして空気感のあるディテールを備えた没入型の情景を提示します。', 'Develop deeper knowledge of dramatic low-angle framing, particle and motion effects, and high-energy anime illustration techniques through layered composition and atmospheric detail.', '重層的な構成と空気感のあるディテールを通じて、劇的なローアングル構図、パーティクルとモーション効果、躍動感あふれるアニメイラスト技法の知識をより深めることができます。', 320.00, 320.00, 320.00, 320, NULL, NULL),
(15, 5, 'Large', '大きい', '(8192 × 8192 px) – The large-format version transforms Neon Idol Stage Debut into a fully immersive visual experience designed for canvas prints, galleries, luxury interiors, and large wall installations. Every detail of the magenta and cyan stage lights, falling confetti, and the ocean of glowing lightsticks is rendered with exceptional clarity and depth in this premium resolution, turning any environment into a striking artistic statement with gallery-quality presence.', '（8192 × 8192 px）大サイズ版は、「Neon Idol Stage Debut」を完全没入型のビジュアル体験へと昇華させたプレミアム仕様です。マゼンタとシアンのステージ照明、舞い散る紙吹雪、光り輝くペンライトの海が超高精細に描写され、キャンバスプリント、ギャラリー展示、高級インテリア、大型ウォールアートに最適な、圧倒的な存在感を放つ作品となります。', 'The Neon Idol Stage Debut artwork transforms interiors through expansive compositions featuring dynamic concert scene composition, stage lighting effects, and idol culture visual energy and visually rich, gallery-scale artistic storytelling.', '「Neon Idol Stage Debut」は、ダイナミックなライブシーンの構成、ステージ照明の効果、アイドル文化の視覚的エネルギーと視覚的に豊かなギャラリースケールの芸術表現を備えた壮大な構成で、空間を一変させます。', 'Explore an expansive artistic presentation of dramatic low-angle framing, particle and motion effects, and high-energy anime illustration techniques through immersive, gallery-scale visual storytelling.', '没入型のギャラリースケールの視覚表現を通じて、劇的なローアングル構図、パーティクルとモーション効果、躍動感あふれるアニメイラスト技法の壮大な芸術的プレゼンテーションを体験できます。', 480.00, 480.00, 480.00, 480, NULL, NULL),
